            'unmatched-researched-20261013-ca' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CA,
            'unmatched-researched-20261013-cb' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CB,
            'unmatched-researched-20261013-cc' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CC,
            'unmatched-researched-20261013-cd' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CD,
            'unmatched-researched-20261013-ce' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CE,
            'unmatched-researched-20261013-cf' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CF,
            'unmatched-researched-20261013-cg' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CG,
            'unmatched-researched-20261013-ch' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CH,
            'unmatched-researched-20261013-ci' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CI,
            'unmatched-researched-20261013-cj' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CJ,
            'unmatched-researched-20261013-ck' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CK,
            'unmatched-researched-20261013-cl' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CL,
            'unmatched-researched-20261013-cm' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CM,
            'unmatched-researched-20261013-cn' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CN,
            'unmatched-researched-20261013-co' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CO,
            'unmatched-researched-20261013-cp' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CP,
            'unmatched-researched-20261013-cq' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CQ,
            'unmatched-researched-20261013-cr' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CR,
            'unmatched-disputed-20261013-cs' => self::BATCH_UNMATCHED_DISPUTED_20261013_CS,
            'unmatched-researched-20261013-ct' => self::BATCH_UNMATCHED_RESEARCHED_20261013_CT,
            'unmatched-researched-20261014-cu' => self::BATCH_UNMATCHED_RESEARCHED_20261014_CU,
            'unmatched-researched-20261014-cv' => self::BATCH_UNMATCHED_RESEARCHED_20261014_CV,
            'unmatched-researched-20261014-cw' => self::BATCH_UNMATCHED_RESEARCHED_20261014_CW,
            'unmatched-disputed-20261014-cx' => self::BATCH_UNMATCHED_DISPUTED_20261014_CX,
            'unmatched-researched-20261014-cy' => self::BATCH_UNMATCHED_RESEARCHED_20261014_CY,
            'unmatched-researched-20261014-cz' => self::BATCH_UNMATCHED_RESEARCHED_20261014_CZ,
            'unmatched-researched-20261014-da' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DA,
            'unmatched-researched-20261014-db' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DB,
            'unmatched-researched-20261014-dc' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DC,
            'unmatched-researched-20261014-dd' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DD,
            'unmatched-researched-20261014-de' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DE,
            'unmatched-disputed-20261014-df' => self::BATCH_UNMATCHED_DISPUTED_20261014_DF,
            'unmatched-disputed-20261014-dg' => self::BATCH_UNMATCHED_DISPUTED_20261014_DG,
            'unmatched-disputed-20261014-dh' => self::BATCH_UNMATCHED_DISPUTED_20261014_DH,
            'unmatched-researched-20261014-di' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DI,
            'unmatched-researched-20261014-dj' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DJ,
            'unmatched-researched-20261014-dk' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DK,
            'unmatched-disputed-20261014-dl' => self::BATCH_UNMATCHED_DISPUTED_20261014_DL,
            'unmatched-researched-20261014-dm' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DM,
            'unmatched-disputed-20261014-dn' => self::BATCH_UNMATCHED_DISPUTED_20261014_DN,
            'not-for-site-unmatched-20261014-do' => self::BATCH_NOT_FOR_SITE_UNMATCHED_20261014_DO,
            'unmatched-researched-20261014-dp' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DP,
            'unmatched-researched-20261014-dq' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DQ,
            'unmatched-disputed-20261014-dr' => self::BATCH_UNMATCHED_DISPUTED_20261014_DR,
            'unmatched-researched-20261014-ds' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DS,
            'unmatched-researched-20261014-dt' => self::BATCH_UNMATCHED_RESEARCHED_20261014_DT,
            default => null,
        };

        if ($rows === null) {
            $this->error('Unknown batch.');

            return self::FAILURE;
        }

        $codes = array_values(array_filter(array_map('strval', (array) $this->option('code'))));
        if ($codes !== []) {
            $rows = array_intersect_key($rows, array_flip($codes));
        }

        $apply = (bool) $this->option('apply');
        $stats = array_fill_keys(['configured', 'ready', 'created', 'linked', 'refreshed', 'ignored', 'disputed', 'brands_created', 'categories_created', 'already', 'blocked'], 0);
        $stats['configured'] = count($rows);
        $details = [];

        foreach ($rows as $code => $rule) {
            $items = IntegrationProduct::query()->with(['source', 'product'])->where('external_code', $code)->get();

            if ($rule['ignore_unmatched_not_for_site'] ?? false) {
                if ($items->count() !== 1) {
                    $stats['blocked']++;
                    $details[] = [$code, '-', 'blocked', 'missing unique 1C row'];

                    continue;
                }

                $item = $items->first();
                if ($item->match_status === 'ignored' && $item->match_method === 'manual_ignore' && ! $item->product_id) {
                    $stats['already']++;
                    $details[] = [$code, '-', 'already', 'item is already excluded from the site'];

                    continue;
                }

                $valid = $item->source?->name === self::SOURCE_NAME
                    && $item->source?->partnerName() === self::PARTNER_NAME
                    && $item->match_status === 'unmatched'
                    && ! $item->product_id
                    && (float) $item->stock_quantity > 0
                    && $item->external_id === $rule['external_id']
                    && $this->containsAll($item->name, $rule['fragments']);

                if (! $valid) {
                    $stats['blocked']++;
                    $details[] = [$code, '-', 'blocked', 'source, identity, stock or status guard failed'];

                    continue;
                }

                $stats['ready']++;
                if ($apply) {
                    $item->forceFill([
                        'product_id' => null,
                        'target_category_id' => null,
                        'match_status' => 'ignored',
                        'match_method' => 'manual_ignore',
                        'match_confidence' => null,
                        'matched_at' => null,
                        'candidates' => null,
                    ])->save();
                    $stats['ignored']++;
                    $details[] = [$code, '-', 'ignored', 'confirmed archived item excluded from the public catalog'];
                } else {
                    $details[] = [$code, '-', 'ready', 'exclude confirmed archived item from the site'];
                }

                continue;
            }

            if ($rule['document_dispute'] ?? false) {
                if ($items->count() !== 1) {
                    $stats['blocked']++;
                    $details[] = [$code, '-', 'blocked', 'missing unique 1C row'];

                    continue;
                }

                $item = $items->first();
                if ($item->match_status === 'ambiguous'
                    && $item->match_method === 'manual_research_unresolved'
                    && ! $item->product_id) {
                    $stats['already']++;
                    $details[] = [$code, '-', 'already', 'research dispute is already documented'];

                    continue;
                }

                $normalizedPrice = $item->normalizedPriceByn();
                $valid = $item->source?->name === self::SOURCE_NAME
                    && $item->source?->partnerName() === self::PARTNER_NAME
                    && $item->match_status === 'unmatched'
                    && ! $item->product_id
                    && (float) $item->stock_quantity > 0
                    && $item->external_id === $rule['external_id']
                    && blank($item->external_sku)
                    && blank($item->barcode)
                    && (isset($rule['expected_price_byn'])
                        ? $normalizedPrice !== null && abs($normalizedPrice - (float) $rule['expected_price_byn']) < 0.01
                        : $normalizedPrice === null)
                    && $this->containsAll($item->name, $rule['fragments']);

                if (! $valid) {
                    $stats['blocked']++;
                    $details[] = [$code, '-', 'blocked', 'source, identity, stock or missing-data guard failed'];

                    continue;
                }

                $stats['ready']++;
                if ($apply) {
                    $item->forceFill([
                        'product_id' => null,
                        'match_status' => 'ambiguous',
                        'match_method' => 'manual_research_unresolved',
                        'match_confidence' => null,
                        'candidates' => [[
                            'type' => 'research_dispute',
                            'name' => 'Спор: недостаточно данных 1С',
                            'reason' => $rule['reason'],
                            'required_data' => $rule['required_data'],
                            'evidence' => $rule['evidence'],
                            'source_identity' => [
                                'external_id' => $item->external_id,
                                'external_code' => $item->external_code,
                                'external_sku' => $item->external_sku,
                                'barcode' => $item->barcode,
                                'name' => $item->name,
                            ],
                        ]],
                        'matched_at' => null,
                    ])->save();
                    $stats['disputed']++;
                    $details[] = [$code, '-', 'disputed', 'insufficient source identity; evidence and required data recorded'];
                } else {
                    $details[] = [$code, '-', 'ready', 'document unresolved research dispute'];
                }

                continue;
            }

            if ($rule['correct_linked_product'] ?? false) {
                $product = Product::query()->where('sku', $rule['product_sku'])->first();
                if ($items->count() !== 1 || ! $product) {
                    $stats['blocked']++;
                    $details[] = [$code, $rule['product_sku'], 'blocked', 'missing unique 1C row or linked product'];

                    continue;
                }

                $item = $items->first();
                $alreadyCorrected = $product->slug === $rule['product_slug']
                    && $product->name === $rule['name']
                    && (string) $product->price === number_format((float) $rule['retail'], 2, '.', '')
                    && collect($product->specs)->contains(
                        fn (array $spec): bool => ($spec['key'] ?? null) === 'Длина'
                            && ($spec['value'] ?? null) === '2 м'
                    );
                if ($alreadyCorrected) {
                    $stats['already']++;
                    $details[] = [$code, $product->sku, 'already', 'linked card identity is already corrected'];

                    continue;
                }

                $valid = $item->source?->name === self::SOURCE_NAME
                    && $item->source?->partnerName() === self::PARTNER_NAME
                    && $item->external_id === $rule['external_id']
                    && $item->match_status === 'matched'
                    && $item->match_method === 'manual_created'
                    && (int) $item->product_id === (int) $product->id
                    && (float) $item->stock_quantity > 0
                    && $product->slug === $rule['current_slug']
                    && $this->containsAll($item->name, $rule['fragments'])
                    && $this->containsAll($product->name, $rule['product_fragments'])
                    && $this->hasNoKnownWatermarkSource($rule['images']);

                if (! $valid) {
                    $stats['blocked']++;
                    $details[] = [$code, $product->sku, 'blocked', 'source, identity, stock or linked-product guard failed'];

                    continue;
                }

                $stats['ready']++;
                if ($apply) {
                    $product->forceFill([
                        'brand_id' => null,
                        'name' => $rule['name'],
                        'h1' => $rule['name'],
                        'slug' => $rule['product_slug'],
                        'price' => round((float) $rule['retail'], 2),
                        'currency' => 'BYN',
                        'short_description' => $rule['short'],
                        'content' => $rule['content'],
                        'images' => $rule['images'],
                        'specs' => $rule['specs'],
                        'content_source_url' => $rule['source_url'],
                        'meta_title' => Str::limit($rule['name'].' — купить в Беларуси | KOTLOV', 255, ''),
                        'meta_description' => Str::limit('Купить '.$rule['name'].' в KOTLOV. Характеристики, актуальная цена и наличие, доставка по Беларуси.', 255, ''),
                        'is_active' => true,
                        'is_archived' => false,
                    ])->save();
                    $stats['refreshed']++;
                    $details[] = [$code, $product->sku, 'corrected', Str::limit($product->name, 58)];
                } else {
                    $details[] = [$code, $product->sku, 'ready', 'correct 2 m identity before creating 3 m card'];
                }

                continue;
            }

            if ($rule['archive_linked_product'] ?? false) {
                $product = Product::query()
                    ->where('sku', $rule['product_sku'])
                    ->where('slug', $rule['product_slug'])
                    ->first();
                if ($items->count() !== 1 || ! $product) {
                    $stats['blocked']++;
                    $details[] = [$code, $rule['product_sku'], 'blocked', 'missing unique 1C row or archived product'];

                    continue;
                }

                $item = $items->first();
                $alreadyArchived = $item->match_status === 'ignored'
                    && $item->match_method === 'manual_ignore'
                    && ! $item->product_id
                    && ! $product->is_active
                    && $product->is_archived;
                if ($alreadyArchived) {
                    $stats['already']++;
                    $details[] = [$code, $product->sku, 'already', 'archived product is already excluded from the site'];

                    continue;
                }

                $valid = $item->source?->name === self::SOURCE_NAME
                    && $item->source?->partnerName() === self::PARTNER_NAME
                    && $item->match_status === 'matched'
                    && $item->match_method === 'manual_created'
                    && (int) $item->product_id === (int) $product->id
                    && (float) $item->stock_quantity > 0
                    && $this->containsAll($item->name, $rule['fragments'])
                    && $this->containsAll($product->name, $rule['product_fragments']);

                if (! $valid) {
                    $stats['blocked']++;
                    $details[] = [$code, $product->sku, 'blocked', 'source, identity, stock or linked-product guard failed'];

                    continue;
                }

                $stats['ready']++;
                if ($apply) {
                    $product->forceFill([
                        'is_active' => false,
                        'is_archived' => true,
                        'in_stock' => false,
                        'stock_qty' => null,
                    ])->save();
                    $item->forceFill([
                        'product_id' => null,
                        'match_status' => 'ignored',
                        'match_method' => 'manual_ignore',
                        'match_confidence' => null,
                        'matched_at' => null,
                    ])->save();
                    $stats['ignored']++;
                    $details[] = [$code, $product->sku, 'archived', 'linked archived product excluded from the public catalog'];
                } else {
                    $details[] = [$code, $product->sku, 'ready', 'archive linked product and mark as not for site'];
                }

                continue;
            }

            if (
                ($rule['ignore_archived'] ?? false)
                || ($rule['ignore_not_for_site'] ?? false)
            ) {
                $candidate = Product::query()->where('slug', $rule['candidate_slug'])->first();
                if ($items->count() !== 1 || ! $candidate) {
                    $stats['blocked']++;
                    $details[] = [$code, $rule['candidate_slug'], 'blocked', 'missing unique 1C row or expected candidate'];

                    continue;
                }

                $item = $items->first();
                if ($item->match_status === 'ignored' && $item->match_method === 'manual_ignore' && ! $item->product_id) {
                    $stats['already']++;
                    $details[] = [$code, '-', 'already', 'item is already excluded from the site'];

                    continue;
                }

                $candidateIds = collect($item->candidates)->pluck('product_id')->map(fn ($id): int => (int) $id);
                $valid = $item->source?->name === self::SOURCE_NAME
                    && $item->source?->partnerName() === self::PARTNER_NAME
                    && $item->match_status === 'ambiguous'
                    && ! $item->product_id
                    && (float) $item->stock_quantity > 0
                    && $candidateIds->contains((int) $candidate->id)
                    && $this->containsAll($item->name, $rule['fragments']);

                if (! $valid) {
                    $stats['blocked']++;
                    $details[] = [$code, $rule['candidate_slug'], 'blocked', 'source, identity, stock or candidate guard failed'];

                    continue;
                }

                $stats['ready']++;
                if ($apply) {
                    $item->forceFill([
                        'product_id' => null,
                        'match_status' => 'ignored',
                        'match_method' => 'manual_ignore',
                        'match_confidence' => null,
                        'matched_at' => null,
                    ])->save();
                    $stats['ignored']++;
                    $details[] = [$code, '-', 'ignored', 'item excluded from the public catalog'];
                } else {
                    $details[] = [$code, '-', 'ready', 'mark as not for site'];
                }

                continue;
            }

            $allowUnmatched = (bool) ($rule['allow_unmatched'] ?? false);
            $templateReference = $rule['template'] ?? $rule['template_slug'];
            $template = isset($rule['template_slug'])
                ? Product::query()->where('slug', $rule['template_slug'])->first()
                : Product::query()->where('sku', $rule['template'])->first();
            $expectedCandidate = $allowUnmatched
                ? null
                : Product::query()->where('sku', $rule['candidate'] ?? $rule['template'])->first();
            $linkConfigured = isset($rule['link_existing_sku']) || isset($rule['link_existing_slug']);
            $linkProduct = isset($rule['link_existing_slug'])
                ? Product::query()->where('slug', $rule['link_existing_slug'])->first()
                : (isset($rule['link_existing_sku'])
                    ? Product::query()->where('sku', $rule['link_existing_sku'])->first()
                    : null);

            if ($items->count() !== 1 || ! $template || (! $allowUnmatched && ! $expectedCandidate)
                || ($linkConfigured && ! $linkProduct)) {
                $stats['blocked']++;
                $details[] = [$code, $templateReference, 'blocked', 'missing unique 1C row or template'];

                continue;
            }

            $item = $items->first();
            $portableImages = $rule['images'] ?? $this->portableImages($template);
            if ($item->product_id) {
                $isExpectedExistingLink = $linkProduct
                    && $item->match_status === 'matched'
                    && $item->match_method === 'manual_search'
                    && (int) $item->product_id === (int) $linkProduct->id;

                if ($isExpectedExistingLink && ($rule['refresh_existing'] ?? false)) {
                    $stats['ready']++;
                    if ($apply) {
                        if (isset($rule['brand']) && ! $this->findBrand($rule['brand'])) {
                            $this->createBrand($rule['brand']);
                            $stats['brands_created']++;
                        }
                        $this->refreshExistingProduct($linkProduct, $rule, $portableImages);
                        $stats['refreshed']++;
                        $details[] = [$code, $linkProduct->sku, 'refreshed', Str::limit($linkProduct->name, 58)];
                    } else {
                        $details[] = [$code, $linkProduct->sku, 'ready', 'existing exact card refresh'];
                    }
                } elseif ($item->match_status === 'matched' && $item->match_method === 'manual_created') {
                    $canRefresh = ($rule['refresh_existing'] ?? false)
                        && $item->product
                        && $item->product->name === ($rule['name'] ?? null)
                        && $item->source?->name === self::SOURCE_NAME
                        && $item->source?->partnerName() === self::PARTNER_NAME
                        && $this->hasNoKnownWatermarkSource($portableImages)
                        && (! isset($rule['external_sku']) || $item->external_sku === $rule['external_sku']);

                    if ($canRefresh) {
                        $stats['ready']++;
                        if ($apply) {
                            $item->product->forceFill([
                                'brand_id' => ($rule['force_brandless'] ?? false)
                                    ? null
                                    : $item->product->brand_id,
                                'short_description' => $rule['short'] ?? $item->product->short_description,
                                'content' => $rule['content'] ?? $item->product->content,
                                'images' => $portableImages,
                                'content_source_url' => $rule['source_url'] ?? $item->product->content_source_url,
                            ])->save();
                            $stats['refreshed']++;
                            $details[] = [$code, $item->product->sku, 'refreshed', Str::limit($item->product->name, 58)];
                        } else {
                            $details[] = [$code, $item->product->sku, 'ready', 'public content refresh'];
                        }
                    } else {
                        $stats['already']++;
                        $details[] = [$code, $item->product?->sku ?: '-', 'already', Str::limit($item->product?->name ?: '', 58)];
                    }
                } else {
                    $stats['blocked']++;
                    $details[] = [$code, $templateReference, 'blocked', 'already linked by another method'];
                }

                continue;
            }

            $candidateIds = collect($item->candidates)->pluck('product_id')->map(fn ($id): int => (int) $id);
            $normalizedPrice = $item->normalizedPriceByn();
            $allowedMatchStatuses = $rule['allowed_match_statuses']
                ?? [($allowUnmatched ? 'unmatched' : 'ambiguous')];
            $configuredBrand = $rule['brand'] ?? null;
            $brand = ($rule['force_brandless'] ?? false)
                ? null
                : ($configuredBrand ? $this->findBrand($configuredBrand) : $template->brand);
            $category = $this->categoryForRule($rule, $template);
            $brandName = trim((string) ($configuredBrand['name'] ?? $brand?->name));
            $name = $rule['name'] ?? $this->productName($brandName, $item->name);
            $nameCollision = $linkProduct
                ? null
                : Product::query()->where('name', $name)->first();
            $plannedNameRelease = $nameCollision && collect($rows)->contains(
                fn (array $batchRule): bool => ($batchRule['correct_linked_product'] ?? false)
                    && ($batchRule['product_sku'] ?? null) === $nameCollision->sku
                    && ($batchRule['name'] ?? null) !== $name
            );
            $valid = $item->source?->name === self::SOURCE_NAME
                && $item->source?->partnerName() === self::PARTNER_NAME
                && in_array($item->match_status, $allowedMatchStatuses, true)
                && (float) $item->stock_quantity > 0
                && ($normalizedPrice !== null || isset($rule['retail']))
                && $category
                && ($brand || $configuredBrand || ($rule['allow_brandless'] ?? false))
                && $portableImages !== []
                && $this->hasNoKnownWatermarkSource($portableImages)
                && ($allowUnmatched || $candidateIds->contains((int) $expectedCandidate->id))
                && $this->containsAll($item->name, $rule['fragments'])
                && (! isset($rule['external_sku'])
                    || $item->external_sku === $rule['external_sku']
                    || (($rule['hydrate_external_sku'] ?? false) && blank($item->external_sku)))
                && ($linkProduct
                    ? $this->containsAll($linkProduct->name, $rule['link_fragments'] ?? [$rule['link_existing_sku'] ?? $rule['link_existing_slug']])
                    : ! $nameCollision || $plannedNameRelease);

            if (! $valid) {
                $stats['blocked']++;
                $details[] = [$code, $templateReference, 'blocked', 'source, identity, price, category, brand, image or candidate guard failed'];

                continue;
            }

            $stats['ready']++;
            $retail = isset($rule['retail'])
                ? (float) $rule['retail']
                : $this->retailPrice((float) $normalizedPrice, (float) $template->price);
            if ($normalizedPrice !== null && $retail < $normalizedPrice) {
                $stats['ready']--;
                $stats['blocked']++;
                $details[] = [$code, $templateReference, 'blocked', 'configured retail price is below supplier price'];

                continue;
            }

            if ($apply) {
                if (! $category->exists) {
                    $category = $this->createCategory($rule['category']);
                    $stats['categories_created']++;
                }

                if (($rule['hydrate_external_sku'] ?? false) && blank($item->external_sku)) {
                    $item->forceFill(['external_sku' => $rule['external_sku']])->save();
                }

                if (! $brand && $configuredBrand) {
                    $brand = $this->createBrand($configuredBrand);
                    $stats['brands_created']++;
                }

                if ($linkProduct) {
                    $linked = DB::transaction(function () use (
                        $item, $linkProduct, $rule, $portableImages, $category, $matchDecision
                    ): ?Product {
                        $linked = $matchDecision->linkSelectedProduct($item, $linkProduct->id);
                        if (! $linked) {
                            return null;
                        }

                        $this->refreshExistingProduct($linked, $rule, $portableImages);
                        $item->forceFill([
                            'target_category_id' => $category->id,
                            'candidates' => null,
                        ])->save();

                        return $linked->fresh();
                    });

                    if (! $linked) {
                        $stats['blocked']++;
                        $details[] = [$code, $linkProduct->sku, 'blocked', 'row changed during exact link'];

                        continue;
                    }

                    $stats['linked']++;
                    $details[] = [$code, $linked->sku, 'linked', number_format($retail, 2, '.', '').' BYN · '.$linked->name];

                    continue;
                }

                $product = $creator->createAndLink($item, [
                    'name' => $name,
                    'category_id' => $category->id,
                    'retail_price' => $retail,
                    'brand_id' => $brand?->id,
                    'h1' => $name,
                    'short_description' => $rule['short'] ?? $this->shortDescription($name),
                    'content' => $rule['content'] ?? $this->content($name, (string) $item->external_sku),
                    'images' => $portableImages,
                    'specs' => $rule['specs'] ?? $this->specs($item),
                    'content_source_url' => $rule['source_url'] ?? null,
                    'meta_title' => Str::limit($name.' — купить в Беларуси | KOTLOV', 255, ''),
                    'meta_description' => Str::limit('Купить '.$name.' в KOTLOV. Характеристики, актуальная цена и наличие, доставка по Беларуси.', 255, ''),
                ]);

                if (! $product) {
                    $stats['blocked']++;
                    $details[] = [$code, $templateReference, 'blocked', 'row changed during create'];

                    continue;
                }

                $stats['created']++;
                $details[] = [$code, $product->sku, 'created', number_format($retail, 2, '.', '').' BYN · '.$name];
            } else {
                $details[] = [$code, $templateReference, 'ready', number_format($retail, 2, '.', '').' BYN · '.$name];
            }
        }

        $this->line($apply ? 'APPLY: verified product cards were created.' : 'DRY RUN: no database changes.');
        $this->table(['1C code', 'template/new SKU', 'status', 'detail'], $details);
        $this->table(['metric', 'count'], collect($stats)->map(fn ($count, $metric) => [$metric, $count])->values()->all());

        return $stats['blocked'] === 0 ? self::SUCCESS : self::FAILURE;
    }

    /** @param array<string, mixed> $rule @param list<string> $portableImages */
    private function refreshExistingProduct(Product $product, array $rule, array $portableImages): void
    {
        $name = (string) ($rule['name'] ?? $product->name);
        $category = isset($rule['category_slug'])
            ? Category::query()->where('slug', $rule['category_slug'])->first()
            : null;
        if ($category && ($rule['refresh_category'] ?? false) && isset($rule['category'])) {
            $config = $rule['category'];
            $parent = Category::query()->where('slug', $config['parent_slug'])->firstOrFail();
            $category->forceFill([
                'parent_id' => $parent->id,
                'name' => $config['name'],
                'h1' => $config['h1'] ?? $config['name'],
                'type' => $config['type'] ?? 'main-child',
                'sort_order' => $config['sort_order'] ?? 0,
                'is_active' => true,
                'content' => $config['content'] ?? null,
                'meta_title' => $config['meta_title'] ?? null,
                'meta_description' => $config['meta_description'] ?? null,
            ])->save();
        }

        $product->forceFill([
            'category_id' => $category?->id ?? $product->category_id,
            'brand_id' => isset($rule['brand'])
                ? $this->findBrand($rule['brand'])?->id ?? $product->brand_id
                : $product->brand_id,
            'name' => $name,
            'h1' => $name,
            'price' => isset($rule['retail']) ? round((float) $rule['retail'], 2) : $product->price,
            'currency' => 'BYN',
            'short_description' => $rule['short'] ?? $product->short_description,
            'content' => $rule['content'] ?? $product->content,
            'images' => $portableImages,
            'specs' => $rule['specs'] ?? $product->specs,
            'content_source_url' => $rule['source_url'] ?? $product->content_source_url,
            'requires_price_confirmation' => ($rule['clear_price_confirmation'] ?? false)
                ? false
                : $product->requires_price_confirmation,
            'meta_title' => Str::limit($name.' — купить в Беларуси | KOTLOV', 255, ''),
            'meta_description' => Str::limit('Купить '.$name.' в KOTLOV. Характеристики, актуальная цена и наличие, доставка по Беларуси.', 255, ''),
            'is_active' => true,
            'is_archived' => false,
        ])->save();
    }

    /** @param array<string, mixed> $rule */
    private function categoryForRule(array $rule, Product $template): ?Category
    {
        if (! isset($rule['category_slug'])) {
            return $template->category;
        }

        $category = Category::query()->where('slug', $rule['category_slug'])->first();
        if ($category) {
            return $category;
        }

        $config = $rule['category'] ?? null;
        if (! is_array($config) || ($config['slug'] ?? null) !== $rule['category_slug']) {
            return null;
        }

        $parent = Category::query()->where('slug', $config['parent_slug'] ?? '')->first();
        if (! $parent) {
            return null;
        }

        return new Category([
            'parent_id' => $parent->id,
            'name' => $config['name'],
            'slug' => $config['slug'],
            'h1' => $config['h1'] ?? $config['name'],
            'type' => $config['type'] ?? 'main-child',
            'sort_order' => $config['sort_order'] ?? 0,
            'is_active' => true,
            'content' => $config['content'] ?? null,
            'meta_title' => $config['meta_title'] ?? null,
            'meta_description' => $config['meta_description'] ?? null,
        ]);
    }

    /** @param array<string, mixed> $config */
    private function createCategory(array $config): Category
    {
        $parent = Category::query()->where('slug', $config['parent_slug'])->firstOrFail();

        return Category::query()->firstOrCreate([
            'slug' => $config['slug'],
        ], [
            'parent_id' => $parent->id,
            'name' => $config['name'],
            'h1' => $config['h1'] ?? $config['name'],
            'type' => $config['type'] ?? 'main-child',
            'sort_order' => $config['sort_order'] ?? 0,
            'is_active' => true,
            'content' => $config['content'] ?? null,
            'meta_title' => $config['meta_title'] ?? null,
            'meta_description' => $config['meta_description'] ?? null,
        ]);
    }

    /** @param array{name:string,slug:string} $config */
    private function findBrand(array $config): ?Brand
    {
        return Brand::query()
            ->where('slug', $config['slug'])
            ->orWhereRaw('LOWER(name) = ?', [mb_strtolower($config['name'])])
            ->first();
    }

    /** @param array{name:string,slug:string,country?:string,content?:string} $config */
    private function createBrand(array $config): Brand
    {
        return Brand::query()->create([
            'name' => $config['name'],
            'slug' => $config['slug'],
            'h1' => $config['name'],
            'country' => $config['country'] ?? null,
            'content' => $config['content'] ?? null,
            'meta_title' => $config['name'].' — официальный каталог бренда | KOTLOV',
            'meta_description' => 'Товары бренда '.$config['name'].' в каталоге KOTLOV: характеристики, актуальные цены и доставка по Беларуси.',
            'is_active' => true,
            'is_featured' => false,
            'sort_order' => 0,
        ]);
    }

    private function retailPrice(float $wholesale, float $templateRetail): float
    {
        $withMargin = $wholesale / 0.70;

        return ceil(max($withMargin, $templateRetail) * 20) / 20;
    }

    /** @return list<string> */
    private function portableImages(Product $template): array
    {
        return collect($template->imagePaths())
            ->map(function (string $path, int $index) use ($template): string {
                if (str_starts_with($path, 'http://') || str_starts_with($path, 'https://')
                    || str_starts_with($path, 'product/') || str_starts_with($path, 'products/')
                    || str_starts_with($path, 'img/')) {
                    return $path;
                }

                $resolved = $template->imageUrl($index);

                return str_starts_with($resolved, '/proxy-image/')
                    ? substr($resolved, strlen('/proxy-image/'))
                    : '';
            })
            ->filter()
            ->values()
            ->all();
    }

    /** @param list<string> $images */
    private function hasNoKnownWatermarkSource(array $images): bool
    {
        return collect($images)->every(
            fn (string $image): bool => ! str_contains(mb_strtolower($image), 'pechki66.ru')
        );
    }

    private function productName(string $brand, string $sourceName): string
    {
        $sourceName = trim($sourceName);

        return $brand !== '' && ! str_contains(mb_strtolower($sourceName), mb_strtolower($brand))
            ? $brand.' '.$sourceName
            : $sourceName;
    }

    private function shortDescription(string $name): string
    {
        return Str::limit($name.' — отдельная конфигурация элемента дымоходной системы. Размеры, материал и исполнение указаны в характеристиках; актуальное наличие подтверждается данными 1С.', 230, '');
    }

    private function content(string $name, string $article): string
    {
        $articleText = $article !== '' ? ' Артикул производителя: '.e($article).'.' : '';

        return '<p><strong>'.e($name).'</strong> — самостоятельная товарная конфигурация, которая отличается от близких моделей размером или исполнением.'.$articleText.'</p>'
            .'<p>Перед заказом сверяйте диаметр, длину, марку стали и толщину стенки в характеристиках. Цена и складской остаток поставщика учитываются отдельно от розничной цены сайта.</p>';
    }

    /** @return list<array{key:string,value:string}> */
    private function specs(IntegrationProduct $item): array
    {
        $name = (string) $item->name;
        $specs = [];

        if (preg_match('/\b(304|430)\s*[-\/]\s*(\d[\.,]\d)/u', $name, $match)) {
            $specs[] = ['key' => 'Марка стали', 'value' => 'AISI '.$match[1]];
            $specs[] = ['key' => 'Толщина стали', 'value' => str_replace(',', '.', $match[2]).' мм'];
        }
        if (preg_match('/\bD\s*(\d+(?:[\/-]\d+)?)/ui', $name, $match)) {
            $specs[] = ['key' => 'Диаметр', 'value' => str_replace('-', '/', $match[1]).' мм'];
        } elseif (preg_match('/\b(?:RP|KNSR?)\s*(\d+)\/(\d+)/ui', $name, $match)) {
            $specs[] = ['key' => 'Диаметр', 'value' => $match[1].' мм'];
        }
        if (preg_match('/\bL\s*(\d+)/ui', $name, $match)) {
            $specs[] = ['key' => 'Длина', 'value' => $match[1].' мм'];
        } elseif (preg_match('/\bRP\s*\d+\/(\d+)/ui', $name, $match)) {
            $specs[] = ['key' => 'Длина', 'value' => $match[1].' мм'];
        }
        if (preg_match('/\b(45|87|90)\s*\*/u', $name, $match)) {
            $specs[] = ['key' => 'Угол', 'value' => $match[1].'°'];
        } elseif (preg_match('/\bKNSR?\s*\d+\/(45|90)/ui', $name, $match)) {
            $specs[] = ['key' => 'Угол', 'value' => $match[1].'°'];
        }
        if (preg_match('/\b(\d)\s*(?:сек|S)\b/ui', $name, $match)) {
            $specs[] = ['key' => 'Количество секций', 'value' => $match[1]];
        }
        if ($item->external_sku) {
            $specs[] = ['key' => 'Артикул производителя', 'value' => (string) $item->external_sku];
        }

        return $specs;
    }

    /** @param list<string> $fragments */
    private function containsAll(string $value, array $fragments): bool
    {
        $value = mb_strtolower(str_replace([',', '–', '—', ' '], ['.', '-', '-', ''], $value));

        return collect($fragments)->every(function (string $fragment) use ($value): bool {
            $fragment = mb_strtolower(str_replace([',', '–', '—', ' '], ['.', '-', '-', ''], $fragment));

            return str_contains($value, $fragment);
        });
    }
}
